// OpenWeatherMap - One Call 3.0
// Docs: https://openweathermap.org/api/one-call-3
// Combines current + minutely + hourly + daily + government alerts.

const OWM_URL = "https://api.openweathermap.org/data/3.0/onecall";

export async function fetchOWM(env, lat, lon) {
  const url = new URL(OWM_URL);
  url.searchParams.set("lat", String(lat));
  url.searchParams.set("lon", String(lon));
  url.searchParams.set("appid", env.OWM_API_KEY);
  url.searchParams.set("units", "metric");
  url.searchParams.set("lang", "zh_cn");
  url.searchParams.set("exclude", "minutely"); // save quota, not crucial

  const res = await fetch(url.toString());
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`OWM ${res.status}: ${text.slice(0, 200)}`);
  }
  return res.json();
}
