// Windy Point Forecast API v2
// Docs: https://api.windy.com/point-forecast/docs
// Returns structured weather data for a single lat/lon (双月湾: 22.6, 114.9).

const WINDY_URL = "https://api.windy.com/api/point-forecast/v2";

export async function fetchWindy(env, lat, lon) {
  const params = [
    "wind", "windGust", "temp", "precip",
    "cloud", "humidity", "pressure",
    "waveHeight", "wavePeriod", "waveDirection"
  ].join(",");

  const body = {
    lat: Number(lat),
    lon: Number(lon),
    model: "iconEu",
    parameters: params,
    levels: "surface",
    key: env.WINDY_API_KEY
  };

  const res = await fetch(WINDY_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body)
  });

  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`Windy ${res.status}: ${text.slice(0, 200)}`);
  }
  return res.json();
}
